static void send(unsigned seq,unsigned ts,const uint8_t* data,size_t n){std::vector<uint8_t>p(12+n);p[0]=0x80;p[1]=0x60;p[2]=uint8_t(seq>>8);p[3]=uint8_t(seq);p[4]=uint8_t(ts>>24);p[5]=uint8_t(ts>>16);p[6]=uint8_t(ts>>8);p[7]=uint8_t(ts);for(size_t i=0;i<n;++i)p[12+i]=data[i];callbacks.media(p.data(),p.size(),callbacks.user);receiver->impl_->processOne();tick+=2000;}
