static void finish(GigaBredr&r){r.end();receiver=nullptr;}
static bool prefix(){GigaBredr r;if(!start(r))return false;std::vector<uint8_t> first(FRAME_A,FRAME_A+sizeof FRAME_A);first.insert(first.end(),FRAME_B,FRAME_B+100);send(1,42,first.data(),first.size());auto first_retained=r.impl_->media.retainedState();const auto first_q16=r.impl_->counters.clock.retained_units_q16;send(2,42,FRAME_B+100,sizeof FRAME_B-100);auto final_retained=r.impl_->media.retainedState();auto c=r.impl_->counters.clock;auto stats=r.impl_->counters;std::printf("ADTS_RETAINED first_bytes=%zu first_q16=%u final_bytes=%zu final_q16=%u\n",first_retained.retained_bytes,first_q16,final_retained.retained_bytes,c.retained_units_q16);std::printf("ADTS_PREFIX_TRACE");for(auto x:decoded_units)std::printf(" %u",x);std::printf(" decoded=%llu completed=%llu packets=%llu prepared=%llu errors=%u\n",(unsigned long long)c.decoded_frames,(unsigned long long)c.completed_frames,(unsigned long long)c.completed_packets,(unsigned long long)source.prepared,stats.decode_errors);bool ok=first_retained.retained_bytes==100&&first_q16==13212&&final_retained.retained_bytes==0&&c.retained_units_q16==0&&decoded_units==std::vector<unsigned>{1,2}&&c.decoded_frames==2048&&c.completed_frames==2048&&c.completed_packets==2&&source.prepared==2048&&stats.decode_errors==0;finish(r);return ok;}
static bool fully_partial(){GigaBredr r;if(!start(r))return false;send(1,42,FRAME_A,100);send(2,42,FRAME_A+100,sizeof FRAME_A-100);auto c=r.impl_->counters.clock;bool ok=decoded_units==std::vector<unsigned>{1}&&c.decoded_frames==1024&&c.completed_frames==1024&&c.completed_packets==2&&source.prepared==1024;finish(r);return ok;}
static bool timestamp_change(){GigaBredr r;if(!start(r))return false;send(1,42,FRAME_A,100);send(2,43,FRAME_B,sizeof FRAME_B);auto c=r.impl_->counters.clock;bool ok=decoded_units==std::vector<unsigned>{2}&&c.decoded_frames==1024&&source.prepared==1024;finish(r);return ok;}
static bool reset(){GigaBredr r;if(!start(r))return false;send(1,42,FRAME_A,100);callbacks.stream(false,callbacks.user);auto c=format();c.aac_transport=AacTransport::Adts;bool ok=callbacks.configure(c,callbacks.user)==Status::Ok;callbacks.stream(true,callbacks.user);send(1,42,FRAME_B,sizeof FRAME_B);ok=ok&&decoded_units==std::vector<unsigned>{2}&&source.prepared==1024;finish(r);return ok;}
