static bool suffix_ownership(){detail::MediaAssembler m;auto c=format();c.aac_transport=AacTransport::Adts;if(m.configure(c,500)!=Status::Ok)return false;std::vector<uint8_t> p(12+sizeof FRAME_A+100);p[0]=0x80;p[1]=0x60;p[3]=1;p[7]=42;std::memcpy(p.data()+12,FRAME_A,sizeof FRAME_A);std::memcpy(p.data()+12+sizeof FRAME_A,FRAME_B,100);detail::MediaView v;if(m.feed(p.data(),p.size(),v)!=Status::Ok)return false;const auto before=m.retainedState();detail::MediaView wrong=v;wrong.data++;bool ok=!m.retainDecodedSuffix(v,0)&&!m.retainDecodedSuffix(v,v.bytes)&&!m.retainDecodedSuffix(wrong,sizeof FRAME_A);auto unchanged=m.retainedState();ok=ok&&unchanged.retained_bytes==before.retained_bytes&&unchanged.assembly_generation==before.assembly_generation&&m.retainDecodedSuffix(v,sizeof FRAME_A);auto after=m.retainedState();ok=ok&&after.retained_bytes==100&&after.assembly_generation==before.assembly_generation&&!std::memcmp(v.data,FRAME_B,100);m.consumed();auto cleared=m.retainedState();return ok&&!cleared.retained_bytes&&cleared.assembly_generation!=after.assembly_generation;}
